        vy = 0.0
        vz = 0.0
        weight = 0.0
        for bond in bonds:
            if bond.get('i', -1) != i:
                continue
            j = bond.get('j', -1)
            d = bond.get('distance_A') or 0.0
            if not (0 <= j < n and 0.0 < d < 6.0):
